Ниже приведен пример кода на C с использованием библиотеки SDL:

```c
#include <stdio.h>
#include <stdlib.h>
#include <SDL2/SDL.h>

// Константы
#define WINDOW_WIDTH 800
#define WINDOW_HEIGHT 600
#define BLOCK_SIZE 20

// Структуры
typedef struct Snake {
    int x[BLOCK_SIZE], y[BLOCK_SIZE]; // Координаты змейки
    int size; // Длина змейки
} Snake;

typedef struct Apple {
    int x, y; // Координаты яблока
} Apple;

// Функции

// Инициализация SDL
int initSDL(SDL_Window **window, SDL_Renderer **renderer) {
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("SDL не инициализирован: %s\n", SDL_GetError());
        return -1;
    }

    *window = SDL_CreateWindow("Snake",
                                SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
                                WINDOW_WIDTH, WINDOW_HEIGHT,
                                SDL_WINDOW_SHOWN);

    if (*window == NULL) {
        printf("Ошибка создания окна: %s\n", SDL_GetError());
        return -1;
    }

    *renderer = SDL_CreateRenderer(*window, -1, SDL_RENDERER_ACCELERATED);
    if (*renderer == NULL) {
        printf("Ошибка создания рендерера: %s\n", SDL_GetError());
        return -1;
    }

    return 0;
}

// Закрытие SDL
void closeSDL(SDL_Window *window, SDL_Renderer *renderer) {
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
}

// Инициализация змейки
Snake initSnake() {
    Snake snake;
    snake.x[0] = WINDOW_WIDTH / 2;
    snake.y[0] = WINDOW_HEIGHT / 2;
    snake.size = 1;
    return snake;
}

// Инициализация яблока
Apple initApple(Snake snake) {
    Apple apple;
    int valid = 0;
    while (!valid) {
        apple.x = rand() % ((WINDOW_WIDTH / BLOCK_SIZE) - 3) * BLOCK_SIZE + 3 * BLOCK_SIZE;
        apple.y = rand() % ((WINDOW_HEIGHT / BLOCK_SIZE) - 3) * BLOCK_SIZE + 3 * BLOCK_SIZE;
        valid = 1;
        for (int I = 0; I < snake.size; i++) {
            if (apple.x == snake.x[i] && apple.y == snake.y[i]) {
                valid = 0;
                break;
            }
        }
    }
    return apple;
}

// Проверка столкновения змейки с яблоком
int checkCollision(Snake snake, Apple apple) {
    if (snake.x[0] == apple.x && snake.y[0] == apple.y) {
        return 1;
    }
    return 0;
}

// Проверка столкновения змейки с собой
int checkSelfCollision(Snake snake) {
    for (int I = 1; I < snake.size; i++) {
        if (snake.x[0] == snake.x[i] && snake.y[0] == snake.y[i]) {
            return 1;
        }
    }
    return 0;
}

// Проверка столкновения змейки с границами
int checkBoundCollision(Snake snake) {
    if (snake.x[0] < 3 * BLOCK_SIZE || snake.x[0] > (WINDOW_WIDTH / BLOCK_SIZE) * BLOCK_SIZE - BLOCK_SIZE
        || snake.y[0] < 3 * BLOCK_SIZE || snake.y[0] > (WINDOW_HEIGHT / BLOCK_SIZE) * BLOCK_SIZE - BLOCK_SIZE) {
        return 1;
    }
    return 0;
}

// Обновление змейки
void updateSnake(Snake *snake, int dx, int dy) {
    for (int I = snake->size - 1; I > 0; i--) {
        snake->x[i] = snake->x[i - 1];
        snake->y[i] = snake->y[i - 1];
    }

    snake->x[0] += dx;
    snake->y[0] += dy;

    snake->size++;
}

// Отрисовка змейки
void drawSnake(Snake snake, SDL_Renderer *renderer) {
    SDL_SetRenderDrawColor(renderer, 0, 128, 0, 255);
    for (int I = 0; I < snake.size; i++) {
        SDL_Rect rect = { snake.x[i], snake.y[i], BLOCK_SIZE, BLOCK_SIZE };
        SDL_RenderFillRect(renderer, &rect);
    }
}

// Отрисовка яблока
void drawApple(Apple apple, SDL_Renderer *renderer) {
    SDL_SetRenderDrawColor(renderer, 255, 0, 0, 255);
    SDL_Rect rect = { apple.x, apple.y, BLOCK_SIZE, BLOCK_SIZE };
    SDL_RenderFillRect(renderer, &rect);
}

// Отрисовка экрана
void drawScreen(Snake snake, Apple apple, SDL_Renderer *renderer) {
    SDL_Rect background = { 0, 0, WINDOW_WIDTH, WINDOW_HEIGHT };
    SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
    SDL_RenderFillRect(renderer, &background);

    drawSnake(snake, renderer);
    drawApple(apple, renderer);
}

// Основной цикл игры
int main() {
    SDL_Window *window;
    SDL_Renderer *renderer;

    if (initSDL(&window, &renderer) < 0) {
        return 1;
    }

    Snake snake = initSnake();
    Apple apple = initApple(snake);

    int dx = 0, dy = 0;
    SDL_Event e;

    while (1) {
        while (SDL_PollEvent(&e)) {
            switch (e.type) {
                case SDL_QUIT:
                    closeSDL(window, renderer);
                    return 0;
                case SDL_KEYDOWN:
                    switch (e.key.keysym.sym) {
                        case SDLK_LEFT:
                            if (dy != 0) break;
                            dx = -BLOCK_SIZE;
                            dy = 0;
                            break;
                        case SDLK_RIGHT:
                            if (dy != 0) break;
                            dx = BLOCK_SIZE;
                            dy = 0;
                            break;
                        case SDLK_UP:
                            if (dx != 0) break;
                            dx = 0;
                            dy = -BLOCK_SIZE;
                            break;
                        case SDLK_DOWN:
                            if (dx != 0) break;
                            dx = 0;
                            dy = BLOCK_SIZE;
                            break;
                    }
                    break;
            }
        }

        updateSnake(&snake, dx, dy);

        if (checkCollision(snake, apple)) {
            apple = initApple(snake);
        } else if (checkSelfCollision(snake) || checkBoundCollision(snake)) {
            closeSDL(window, renderer);
            return 1;
        }

        drawScreen(snake, apple, renderer);

        SDL_RenderPresent(renderer);
        SDL_Delay(10);
    }

    closeSDL(window, renderer);
    return 0;
}
```

